package org.wso2.carbon.identity.application.authentication.framework.config.model.graph.js;

import jdk.nashorn.api.scripting.AbstractJSObject;
import org.wso2.carbon.identity.application.common.model.ClaimMapping;

import java.util.Map;

/**
 * Provides array like access to the claims of an authenticated user from the javascript.
 * The claims are keyed by a claim URI, which is resolved from the {@link ClaimMapping} via a provided
 * {@link IdMapper}. This allows the same underlying {@code Map<ClaimMapping, String>} to be exposed as either
 * a local claim view or a remote claim view.
 * e.g
 * var email = context.subject.claims.local["http://wso2.org/claims/emailaddress"]
 * context.subject.claims.local["http://wso2.org/claims/emailaddress"] = "foo@bar.com"
 */
public class JsClaimView extends AbstractJSObject {

    private Map<ClaimMapping, String> claims;
    private IdMapper idMapper;

    public JsClaimView(Map<ClaimMapping, String> claims, IdMapper idMapper) {

        this.claims = claims;
        this.idMapper = idMapper;
    }

    @Override
    public Object getMember(String name) {

        for (Map.Entry<ClaimMapping, String> entry : claims.entrySet()) {
            if (name.equals(idMapper.toId(entry.getKey()))) {
                return entry.getValue();
            }
        }
        return null;
    }

    @Override
    public boolean hasMember(String name) {

        for (Map.Entry<ClaimMapping, String> entry : claims.entrySet()) {
            if (name.equals(idMapper.toId(entry.getKey()))) {
                return true;
            }
        }
        return false;
    }

    @Override
    public void setMember(String name, Object value) {

        for (Map.Entry<ClaimMapping, String> entry : claims.entrySet()) {
            if (name.equals(idMapper.toId(entry.getKey()))) {
                entry.setValue(String.valueOf(value));
                return;
            }
        }
    }

    @Override
    public boolean isArray() {

        return true;
    }

    /**
     * Resolves the claim URI (id) used to key the claim view from a {@link ClaimMapping}.
     */
    @FunctionalInterface
    public interface IdMapper {

        String toId(ClaimMapping claimMapping);
    }
}
