package org.wso2.carbon.identity.application.authentication.framework.config.model.graph.js;

import org.wso2.carbon.identity.application.authentication.framework.util.FrameworkConstants;
import org.wso2.carbon.identity.application.common.model.ClaimMapping;

import java.util.Map;
import java.util.function.Consumer;

/**
 * Javascript wrapper for the set of claims of a Java level AuthenticatedUser.
 * This provides controlled access to the {@code Map<ClaimMapping, String>} of user attributes via provided
 * javascript native syntax.
 * e.g
 * var email = context.subject.claims.local["http://wso2.org/claims/emailaddress"]
 * context.subject.claims.push({local: "...", remote: "...", value: "..."})
 * <p>
 * The claims can be accessed keyed by the local claim URI (via {@code local}) or the remote claim URI
 * (via {@code remote}), and new claims can be added via {@code push}.
 *
 * @see ClaimMapping
 */
public class JsClaimSet extends AbstractJSObjectWrapper<Map<ClaimMapping, String>> {

    private static final JsLogger LOG = JsLogger.getInstance();

    public JsClaimSet(Map<ClaimMapping, String> wrapped) {

        super(wrapped);
    }

    @Override
    public Object getMember(String name) {

        switch (name) {
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_LOCAL:
                return new JsClaimView(getWrapped(),
                        claimMapping -> claimMapping.getLocalClaim() == null ? null
                                : claimMapping.getLocalClaim().getClaimUri());
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_REMOTE:
                return new JsClaimView(getWrapped(),
                        claimMapping -> claimMapping.getRemoteClaim() == null ? null
                                : claimMapping.getRemoteClaim().getClaimUri());
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_PUSH:
                return (Consumer<Object>) this::push;
            default:
                return super.getMember(name);
        }
    }

    @Override
    public boolean hasMember(String name) {

        switch (name) {
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_LOCAL:
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_REMOTE:
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_PUSH:
                return true;
            default:
                return super.hasMember(name);
        }
    }

    /**
     * Constructs a new {@link ClaimMapping} from the given claim object and inserts it into the wrapped user
     * attributes map. The claim object is expected to contain {@code local}, {@code remote} and {@code value}
     * fields. If the {@code value} field is missing, no entry is added.
     *
     * @param claim the claim object pushed from the javascript.
     */
    public void push(Object claim) {

        if (!(claim instanceof Map)) {
            LOG.error("Invalid claim object provided to push. Expected a claim object with local, remote and value "
                    + "fields.");
            return;
        }

        Map claimMap = (Map) claim;
        Object localClaimUri = claimMap.get(FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_LOCAL);
        Object remoteClaimUri = claimMap.get(FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_REMOTE);
        Object value = claimMap.get(FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_VALUE);

        if (value == null) {
            LOG.error("The value of the claim is not provided. Skipping the claim.");
            return;
        }

        ClaimMapping claimMapping = ClaimMapping.build(
                localClaimUri == null ? null : String.valueOf(localClaimUri),
                remoteClaimUri == null ? null : String.valueOf(remoteClaimUri), null, false);
        getWrapped().put(claimMapping, String.valueOf(value));
    }

    public boolean isEmpty() {

        return getWrapped().isEmpty();
    }
}
